import{_ as e,o,c as s,ag as r}from"./chunks/framework.CrXGS008.js";const p=JSON.parse('{"title":"Máquinas de alta pressão","description":"","frontmatter":{},"headers":[],"relativePath":"pt/car-wash/pressure-washers.md","filePath":"pt/car-wash/pressure-washers.md"}'),d={name:"pt/car-wash/pressure-washers.md"};function t(n,a,i,c,l,m){return o(),s("div",null,[...a[0]||(a[0]=[r('<h1 id="maquinas-de-alta-pressao" tabindex="-1">Máquinas de alta pressão <a class="header-anchor" href="#maquinas-de-alta-pressao" aria-label="Permalink to &quot;Máquinas de alta pressão&quot;">​</a></h1><p>As máquinas de alta pressão são a opção self-service: o jogador estaciona, vai até uma máquina e limpa o veículo nível a nível. Cada nível de sujidade removido é pago.</p><h2 id="onde-ficam" tabindex="-1">Onde ficam <a class="header-anchor" href="#onde-ficam" aria-label="Permalink to &quot;Onde ficam&quot;">​</a></h2><p>Há duas formas, que pode usar em simultâneo:</p><ul><li><strong>Props do mundo</strong>: cada prop indicado em <code>ManualModels</code> passa a ser uma máquina de alta pressão, onde quer que o mapa tenha um. Por predefinição é o <code>prop_gas_airunit01</code>, o compressor de ar dos postos de combustível.</li><li><strong>Estações que posiciona</strong>: adicione uma entrada em <code>ManualStations</code> no <code>/nay</code>, coloque-se onde a quer pôr e clique em <strong>Usar a minha posição</strong>.</li></ul><p>Com <code>ShowBlips</code> ativado, as estações posicionadas aparecem no mapa.</p><h2 id="como-os-jogadores-a-usam" tabindex="-1">Como os jogadores a usam <a class="header-anchor" href="#como-os-jogadores-a-usam" aria-label="Permalink to &quot;Como os jogadores a usam&quot;">​</a></h2><ul><li>Com <code>InteractionMode</code> definido como <code>key</code>, os jogadores vão até à máquina e premem <strong>E</strong>.</li><li>Com <code>target</code>, usam o olho do target (ox_target ou qb-target).</li></ul><p>São mostrados o nível de sujidade do veículo e o preço por nível. A limpeza remove um nível a cada <code>ManualSecondsPerLevel</code> segundos, e cada nível custa <code>ManualPricePerLevel</code>, cobrado na conta definida em <code>Account</code>. Os jogadores podem parar a qualquer momento e só pagam o que limparam.</p><p>Desative todas as máquinas de alta pressão com <code>ManualEnabled</code>. Todas as definições estão na página <a href="/pt/car-wash/settings#maquinas-de-alta-pressao">Definições</a>.</p>',10)])])}const h=e(d,[["render",t]]);export{p as __pageData,h as default};
